  input('spAnswer',partial);click('spCheckAnswer');ok(!data.attempts.at(-1).correct,'Unrelated mean not a repeat');ok($('spIdeaFeedback')||d.body.textContent.includes('Repeat the test'),'Missing repeat is explained');ok($('spSaveWriting'),'Can save pending answer without revealing solution');ok(!data.attempts.at(-1).independent,'No automatic written mastery');
  input('spAnswer',q.answer);click('spCheckWriting');ok(data.attempts.at(-1).correct,'Reference passes repaired preliminary check');ok(!data.attempts.at(-1).independent,'Revised reference not independent');click('spSaveWriting');ok(data.attempts.length===1,'Written response saved, no phantom question');ok(S.report(data).writing.pending===1,'Parent report includes pending writing');checks.push('contextual writing, recheck and review queue');
  reset();data=S.init(state());teach(S,data,'circuits');teach(S,data,'measurement');
  for(let i=0;i<3;i++){S.finishPractice(data);const v=S.startPractice(data,'circuits',{phase:'apply',seed:73+i*7919});w.MochiSciencePathUI.open('practice','circuits');input('spAnswer',S.question(v).answer);click('spCheckAnswer');if(i<2)w.MochiTodayUI.open();}
  click('spMorePractice');ok(data.draft.unit==='circuits'&&data.draft.form===2,'Three circuit questions lead to explanatory transfer');ok(S.question(data.draft).kind==='written','New circuit task is not another easy choice');input('spAnswer',S.question(data.draft).answer);click('spCheckAnswer');click('spSaveWriting');ok(data.draft?.unit!=='circuits','Next task leaves circuit loop while review is pending');checks.push('bounded science manual practice');
